)

// parseStruct reads a Go source file and extracts the struct definition.
func parseStruct(filePath string) (map[string]interface{}, error) {
	file, err := os.Open(filePath)
	if err != nil {
		return nil, err
	}
	defer file.Close()

	// Read the entire file content
	content, err := ioutil.ReadAll(file)
	if err != nil {
		return nil, err
	}

	// Parse the JSON data into a map
	var structDef map[string]interface{}
	err = json.Unmarshal(content, &structDef)
	if err != nil {
		return nil, err
	}

	return structDef, nil
}

// generateAvroSchema takes a struct definition and generates an Avro schema file.
func generateAvroSchema(structDef map[string]interface{}, structName string) error {
	// Create the Avro schema
	avroSchema := map[string]interface{}{
		"type":     "record",
		"name":     structName,
		"fields":   generateFields(structDef),
		"doc":      "Generated Avro schema for " + structName,
	}

	// Write the Avro schema to a file
	schemaFile, err := os.Create(fmt.Sprintf("%s.avsc", structName))
	if err != nil {
		return err
	}
	defer schemaFile.Close()

	err = json.NewEncoder(schemaFile).Encode(avroSchema)
	if err != nil {
		return err
	}

	return nil
}

// generateFields generates a list of fields for the Avro schema.
func generateFields(structDef map[string]interface{}) []map[string]interface{} {
	fields := make([]map[string]interface{}, 0)

	for fieldName, fieldDef := range structDef {
		if fieldDef == nil {
			continue
		}

		// Check if the field is a struct
		if isStruct, ok := fieldDef.(map[string]interface{}); ok {
			subFields, err := generateFields(isStruct)
			if err != nil {
				return nil
			}
			fields = append(fields, map[string]interface{}{
				"name": fieldName,
				"type": "record",
				"fields": subFields,
			})
		} else {
			fields = append(fields, map[string]interface{}{
				"name": fieldName,
				"type": "string",
			})
		}
	}

	return fields
}

func main() {
