	filePath := filepath.Join(os.Args[1], structName+".go")
	structDef, err := parseStruct(filePath)
	if err != nil {
		fmt.Printf("Error parsing struct definition: %v\n", err)
		os.Exit(1)
	}

	if err := generateAvroSchema(structDef, structName); err != nil {
		fmt.Printf("Error generating Avro schema: %v\n", err)
