1. Declare a function that takes an array of integers and the size of the array as parameters.
2. Use a for loop to iterate through the array and compare adjacent elements. If the current element is greater than the next element, swap them.
3. After each pass through the array, the largest element will be at the end. So, you can reduce the size of the array by one after each pass.
4. Repeat steps 2 and 3 until the entire array is sorted.
5. Return the sorted array.
Here's an example implementation of the bubble sort algorithm in C++:
```cpp
#include <iostream>
#include <vector>
using namespace std;
void bubbleSort(vector<int>& arr, int size) {
    for (int i = 0; i < size - 1; i++) {
        for (int j = 0; j < size - i - 1; j++) {
            if (arr[j] > arr[j + 1]) {
                swap(arr[j], arr[j + 1]);
            }
        }
    }
}
int main() {
    vector<int> arr = {5, 2, 9, 1, 5, 6};
    int size = arr.size();
    bubbleSort(arr, size);
    cout << "Sorted array: ";
    for (int i = 0; i < size; i++) {
        cout << arr[i] << " ";
    }
    return 0;
}
```
